import{M as e,U as t,W as n,it as r}from"./chunks/framework.D_8Ll7sl.js";var i=JSON.parse(`{"title":"使用","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"usage.md","filePath":"usage.md","lastUpdated":1786873544000}`),a={name:`usage.md`};function o(e,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[n(`<h1 id="usage" tabindex="-1">使用 <a class="header-anchor" href="#usage" aria-label="Permalink to “使用”">​</a></h1><h2 id="invoke" tabindex="-1">调用 <a class="header-anchor" href="#invoke" aria-label="Permalink to “调用”">​</a></h2><p>调用子悦机器的消息应该以 <code>/</code> 或 <code>@子悦机器</code> 开头。当子悦机器遇到不存在的命令名时，将输出“未知命令”。</p><p>子悦机器也会解析不以 <code>/</code> 开头的命令调用。但在这种情况下，遇到不存在的命令名时不会输出“未知命令”。</p><h2 id="parse" tabindex="-1">解析 <a class="header-anchor" href="#parse" aria-label="Permalink to “解析”">​</a></h2><p>子悦机器的一条命令由“命令名”和“参数”组成。命令名为消息第一个空格之前的内容，之后的内容将被视为参数部分。</p><p>子悦机器采用“贪婪解析”机制，命令名之后的所有部分都被视为一个整体。</p><p>例如：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/扔云瓶 子悦解说 EasyT_T 山羊</span></span></code></pre></div><p>这一消息最终会被解析为“调用 <a href="/general/driftbottle/throw">扔云瓶</a> ，并传入参数 <code>子悦解说 EasyT_T 山羊</code>”。</p><h3 id="complex" tabindex="-1">复杂解析 <a class="header-anchor" href="#complex" aria-label="Permalink to “复杂解析”">​</a></h3><p>对于少数需要两个及以上的参数，这些命令会再细分参数，在空格部分分割，并将引号内视为整体。对于这些命令而言，多出的参数将被忽略。</p><p>例如：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/command arg1 &quot;arg2 arg3&quot;</span></span></code></pre></div><p>这一消息会被解析为“调用名为 <code>command</code> 的命令，并传入参数 <code>arg1</code> 和 <code>arg2 arg3</code>”。</p><h2 id="forward" tabindex="-1">回复 <a class="header-anchor" href="#forward" aria-label="Permalink to “回复”">​</a></h2><p>在 QQ 中，如果调用子悦机器的消息回复了某条消息，则被回复的消息将被视为第一个参数。</p><p>例如：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>这是被回复的消息 包括空格</span></span>
<span class="line"><span>------------</span></span>
<span class="line"><span>/command arg1 &quot;arg2 arg3&quot;</span></span></code></pre></div><p>等价于：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/command &quot;这是被回复的消息 包括空格&quot; arg1 &quot;arg2 arg3&quot;</span></span></code></pre></div>`,21)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};